UPDATE public_submission_delivery_state SET status = 'failed', last_outcome_code = CASE WHEN attempt_count >= 5 THEN 'retry_exhausted' ELSE 'delivery_window_elapsed' END, completed_at = unixepoch(), lease_token = NULL, lease_expires_at = NULL, updated_at = unixepoch() WHERE task_id IN (SELECT visible.task_id FROM retained_visible_public_submission_delivery AS visible JOIN public_submission_delivery_state AS state ON state.task_id = visible.task_id WHERE ((state.status = 'pending' AND visible.created_at + 86400 <= unixepoch()) OR (state.status = 'leased' AND state.lease_expires_at <= unixepoch() AND (state.attempt_count >= 5 OR visible.created_at + 86400 <= unixepoch()))) ORDER BY visible.created_at, visible.task_id LIMIT 100)
